.root {
  padding-top: 0.5rem;
}

.reveal {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition: grid-template-rows var(--slide-transition), opacity var(--slide-transition);

  &:global(.open) {
    grid-template-rows: 1fr;
    opacity: 1;
  }
}

.revealClip {
  overflow: hidden;
  min-height: 0;
}

.section > .revealClip {
  overflow: clip;
  overflow-clip-margin: 0.3125rem;
}

.sectionContent {
  padding-top: 1rem;
}

.row {
  cursor: default;
  border-radius: var(--border-radius-default);
  transition: background-color 0.15s ease;
}

.control {
  --control-grid-template-areas: "input before label after" "input before desc desc";
}

.recording {
  background-color: var(--color-chat-hover);
}

.recording .interactive {
  outline: none;
}

.after {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.fixedIcon {
  flex-shrink: 0;
  font-size: 0.75rem;
  color: var(--color-text-secondary);
  opacity: 0.8;
}

.crossfade {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  /* stylelint-disable-next-line plugin/no-low-performance-animation-properties */
  transition: width var(--slide-transition), height var(--slide-transition);
}

.layers {
  isolation: isolate;

  display: grid;
  flex-shrink: 0;
  align-items: center;
  justify-items: end;

  width: max-content;
  max-width: 11rem;
}

.layer {
  grid-area: 1 / 1;
  grid-template-rows: 1fr;
  mix-blend-mode: plus-lighter;
}

.layerEnter:global(.open) {
  @starting-style {
    opacity: 0;
  }
}

.keys {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  align-items: center;
  justify-content: flex-end;
}

.combo {
  display: inline-flex;
  gap: 0.25rem;
  align-items: center;
  white-space: nowrap;
}

.key {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 1.5rem;
  height: 1.5rem;
  padding-bottom: 0.0625rem;
  padding-inline: 0.3125rem;
  border: 0.0625rem solid var(--color-borders-input);
  border-radius: 0.375rem;

  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--color-text-secondary);
  white-space: nowrap;

  background-color: var(--color-background);
  box-shadow: inset 0 -0.0625rem 0 var(--color-borders-input);

  transition: opacity 0.2s ease;
}

.keyLabel {
  /* stylelint-disable-next-line plugin/use-baseline */
  text-box: trim-both cap alphabetic;
}

.keysSeparator {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
}

.recordingText,
.notSet {
  font-size: 0.875rem;
  white-space: nowrap;
}

.recordingKeys .key,
.recordingText {
  color: var(--color-primary);
}

.recordingKeys .key {
  @starting-style {
    opacity: 0;
  }
}

.notSet {
  color: var(--color-text-secondary);
}

.description {
  margin-top: 0;
}

.descriptionBlock {
  display: block;
  padding-top: 0.125rem;
}

.descriptionLine {
  display: block;
}

.error,
.destructive {
  color: var(--color-error);
}

.conflict {
  display: flex;
  gap: 0.25rem;
  align-items: center;
  color: var(--color-warning);
}

.conflictIcon {
  flex-shrink: 0;
  font-size: 1rem;
}

.nothingFound {
  padding-block: 2rem;
}
